drop function if exists public.get_discover_profiles(uuid[],integer);
create or replace function public.get_discover_profiles(p_excluded_ids uuid[] default '{}'::uuid[],p_limit integer default 20)
returns table(id uuid,display_name text,date_of_birth date,gender text,department text,academic_year text,identity_type text,institution_name text,field_of_study text,job_title text,employer_name text,role_description text,bio text,ghost_mode boolean,created_at timestamptz,profile_photos jsonb,profile_interests jsonb)
language sql stable security definer set search_path=public as $function$
with eligible as (select p.id,p.display_name,p.date_of_birth,p.gender,p.department,p.academic_year,p.identity_type,p.institution_name,p.field_of_study,p.job_title,p.employer_name,p.role_description,p.bio,p.ghost_mode,p.created_at,case when(p.gender='woman' or exists(select 1 from public.subscriptions s where s.user_id=p.id and s.plan='pro' and s.status in('trialing','active') and((s.status='trialing' and s.trial_ends_at>now())or(s.status='active' and s.current_period_end>now()))))then random()*0.25 else 0 end as boost from public.profiles p where p.profile_completed=true and p.ghost_mode=false and p.id<>auth.uid() and not(p.id=any(p_excluded_ids)))
select e.id,e.display_name,e.date_of_birth,e.gender,e.department,e.academic_year,e.identity_type,e.institution_name,e.field_of_study,e.job_title,e.employer_name,e.role_description,e.bio,e.ghost_mode,e.created_at,coalesce((select jsonb_agg(jsonb_build_object('storage_path',pp.storage_path,'display_order',pp.display_order,'is_primary',pp.is_primary) order by pp.is_primary desc,pp.display_order asc) from public.profile_photos pp where pp.profile_id=e.id),'[]'::jsonb),coalesce((select jsonb_agg(jsonb_build_object('interests',jsonb_build_object('id',i.id,'name',i.name))) from public.profile_interests pi join public.interests i on i.id=pi.interest_id where pi.profile_id=e.id),'[]'::jsonb) from eligible e order by e.boost desc,e.created_at desc limit greatest(1,least(p_limit,50));
$function$;
